/** Every archived issue of the org, whichever project it sits in. */
export async function listArchivedIssueRefs(orgId: OrgId): Promise<
  readonly {
    id: IssueId;
    projectId: ProjectId;
    number: number;
    archivedAt: IsoTimestamp;
  }[]
> {
  const rows = getDb()
    .select({
      id: issues.id,
      projectId: issues.projectId,
      number: issues.number,
      archivedAt: issues.archivedAt,
    })
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), isNotNull(issues.archivedAt)))
    .all();

  return rows.map((row) => ({
    id: row.id as IssueId,
    projectId: row.projectId as ProjectId,
    number: row.number,
    archivedAt: row.archivedAt as IsoTimestamp,
  }));
}

const BYTES_PER_MB = 1024 * 1024;

export interface PurgeResult {
  readonly issues: number;
  readonly commentIds: readonly string[];
  /** Megabytes the purged attachments were counted for (each rounded up). */
  readonly storageMb: number;
}

/**
 * Permanently deletes issues with their label links, comments and
 * attachments, in one transaction. The highest number each affected project
 * has used is remembered first so numbers are never handed out twice.
 */
export async function purgeIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<PurgeResult> {
  if (issueIds.length === 0) return { issues: 0, commentIds: [], storageMb: 0 };
  const ids = [...issueIds];

  return getDb().transaction((tx) => {
    const rows = tx
      .select({
        id: issues.id,
        projectId: issues.projectId,
        number: issues.number,
      })
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .all();

    const maxByProject = new Map<string, number>();
    for (const row of rows) {
      maxByProject.set(
        row.projectId,
        Math.max(maxByProject.get(row.projectId) ?? 0, row.number),
      );
    }
    for (const [projectId, maxNumber] of maxByProject) {
      tx.insert(projectIssueNumbers)
        .values({ projectId, orgId, maxNumber })
        .onConflictDoUpdate({
          target: projectIssueNumbers.projectId,
          set: {
            maxNumber: sql`max(${projectIssueNumbers.maxNumber}, ${maxNumber})`,
          },
        })
        .run();
